style.css:
@-moz-document domain("Roblox.com") {
/* Set background to your sakura forest image */
  body {
    background: url(https://ca.pinterest.com/pin/10555380371575733/) no-repeat center center fixed !important;
    background-size: cover !important;
    color: #f7e6f7 !important; /* soft pink text */
    font-family: "Segoe UI", Arial, sans-serif !important;
  }

  /* Semi-transparent containers */
  div, section, article {
    background: rgba(20, 10, 20, 0.7) !important;
    border-radius: 12px !important;
    padding: 10px !important;
  }

  /* Links in sakura colors */
  a {
    color: #ff80b3 !important;
  }

  a:hover {
    color: #ffd480 !important; /* warm golden glow */
  }

  /* Buttons styled like glowing lanterns */
  button {
    background: #ffcc66 !important;
    border: none !important;
    color: #2e1a1a !important;
    font-weight: bold !important;
    border-radius: 10px !important;
    box-shadow: 0px 0px 10px #ffcc66 !important;
  }

  button:hover {
    background: #ff9966 !important;
    box-shadow: 0px 0px 15px #ff9966 !important;
  }
}
